    brewer VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Drinker (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Frequents (
    drinker VARCHAR NOT NULL,
    bar VARCHAR NOT NULL,
    times_a_week SMALLINT NOT NULL,
    PRIMARY KEY (drinker, bar),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (bar) REFERENCES Bar(name)
);

CREATE TABLE Serves (
    bar VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    price DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (bar, beer),
    FOREIGN KEY (bar) REFERENCES Bar(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

CREATE TABLE Likes (
    drinker VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    PRIMARY KEY (drinker, beer),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

counterexample:
INSERT INTO Bar (name, address) VALUES ('Bar1', 'Addr1');
INSERT INTO Bar (name, address) VALUES ('Bar2', 'Addr2');
INSERT INTO Bar (name, address) VALUES ('Bar3', 'Addr3');

INSERT INTO Drinker (name, address) VALUES ('Amy', 'DAddr1');
INSERT INTO Drinker (name, address) VALUES ('Bob', 'DAddr2');
INSERT INTO Drinker (name, address) VALUES ('Carl', 'DAddr3');

-- Amy total = 3 (Bar1:2, Bar3:1)
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Amy', 'Bar1', 2);
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Amy', 'Bar3', 1);
-- Bob total = 3 (Bar2:3), no shared bar with Amy
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'Bar2', 3);
-- Carl shares with both, ensures Q2's max comes from (Bob, Carl)
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Carl', 'Bar1', 5);
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Carl', 'Bar2', 5);

